<?php $this->assign('title', 'Apontamento #' . $row->id); ?>
<div class="page-heading"><h1>Apontamento #<?= h($row->id) ?></h1><?php if (!$row->cancelado && $row->controle_pcm!=='lancado' && $currentUser->perfil !== 'RESPONSAVEL_SETOR'): ?><?= $this->Html->link($currentUser->perfil==='ADMIN_PCM'?'Editar hora':'Corrigir descrição', ['action' => 'edit', $row->id], ['class' => 'btn btn-primary']) ?><?php endif; ?></div>
<section class="panel my-4"><?= $this->element('entries_table', ['rows' => [$row]]) ?><?php if(!\App\Service\Access::operational($currentUser)): ?><?= $this->Html->link('Abrir O.S. e totais por funcionário', ['controller' => 'Atividades', 'action' => 'view', $row->atividade_id]) ?><?php else: ?><?= $this->Html->link('Histórico de evolução desta O.S.',['controller'=>'Evolucao','action'=>'historico',$row->atividade_id]) ?><?php endif; ?></section>
<?php if (!$row->cancelado && $currentUser->perfil !== 'RESPONSAVEL_SETOR'): ?><section class="panel my-4"><h2>Controle interno do PCM</h2><p>Esta operação não altera o TOTVS.</p><?= $this->Form->create(null, ['url' => ['action' => 'change', $row->id, '_method' => 'POST']]) ?><div class="row g-3"><div class="col-md-4"><?= $this->Form->control('acao', ['label' => 'Operação', 'options' => ['pendente' => 'Pendente de lançamento no TOTVS', 'conferido' => 'Conferido pelo PCM', 'lancado' => 'Lançado manualmente no TOTVS'], 'class' => 'form-select']) ?></div><div class="col-md-8"><?= $this->Form->control('motivo', ['label' => 'Motivo / referência da confirmação *', 'class' => 'form-control', 'required' => true]) ?></div></div><?= $this->Form->control('confirmar',['type'=>'checkbox','value'=>'1','label'=>'Confirmo a operação informada.']) ?><?= $this->Form->button('Registrar operação', ['class' => 'btn btn-outline-primary mt-3']) ?><?= $this->Form->end() ?></section><?php endif; ?>
<section class="panel"><h2>Histórico de alterações</h2><?php foreach ($audits as $audit): ?><details class="border-bottom py-3"><summary><?= h($audit->created->setTimezone('America/Sao_Paulo')->format('d/m/Y H:i')) ?> · <?= h($audit->usuario_nome) ?> · <?= h($audit->acao) ?></summary><p class="mt-2"><?= h($audit->motivo ?: 'Registro inicial') ?></p><div class="row"><div class="col-md-6"><strong>Antes</strong><pre class="small text-wrap text-break"><?= h(\App\Service\OsApresentacao::audit($audit->antes) ?: 'Sem registro anterior') ?></pre></div><div class="col-md-6"><strong>Depois</strong><pre class="small text-wrap text-break"><?= h(\App\Service\OsApresentacao::audit($audit->depois)) ?></pre></div></div></details><?php endforeach; ?></section>
